WITH wanted(ordinal) AS(VALUES (1)),covering AS(SELECT ordinal,(SELECT first_ordinal FROM metadata_value_group WHERE first_ordinal<=w.ordinal ORDER BY first_ordinal DESC LIMIT 1) first FROM wanted w) SELECT DISTINCT g.first_ordinal,g.count,g.pack_id,g.group_number,g.digest FROM covering c JOIN metadata_value_group g ON g.first_ordinal=c.first WHERE c.ordinal<g.first_ordinal+g.count ORDER BY g.first_ordinal
